        data: {"result": {"minY": 1.0, "minX": 0.0, "maxY": 80.0, "series": [{"data": [[0.0, 38.0], [100.0, 62.0]], "isOverall": false, "label": "Add character", "isController": false}, {"data": [[0.0, 65.0], [100.0, 34.0], [200.0, 1.0]], "isOverall": false, "label": "Get user by id", "isController": false}, {"data": [[0.0, 54.0], [100.0, 46.0]], "isOverall": false, "label": "Delete user", "isController": false}, {"data": [[0.0, 20.0], [100.0, 80.0]], "isOverall": false, "label": "Update user", "isController": false}, {"data": [[600.0, 20.0], [700.0, 39.0], [800.0, 37.0], [900.0, 4.0]], "isOverall": false, "label": "Get all characters", "isController": false}], "supportsControllersDiscrimination": true, "granularity": 100, "maxX": 900.0, "title": "Response Time Distribution"}},
